  "check_code": "from pathlib import Path
import sqlite3


def _db(ws, slug):
    return Path(ws).parent / "system" / slug / "state.db"


def _rows(path, table):
    con = sqlite3.connect(path)
    try:
        return con.execute(f"SELECT * FROM [{table}] ORDER BY 1").fetchall()
    finally:
        con.close()


def _cols(path, table):
    con = sqlite3.connect(path)
    try:
        return [row[1] for row in con.execute(f"PRAGMA table_info([{table}])")]
    finally:
        con.close()


def check_decision_post_state(ws):
    path = _db(ws, "enablon_conversion_gate")
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    try:
        rows = con.execute(
            "SELECT * FROM gate_decisions WHERE conversion_project_id=? "
            "AND gate_code=? AND decision_date=?",
            ("CP-2025-017", "GATE_WELL_LOOP_VALIDATION", "2025-08-18"),
        ).fetchall()
        if len(rows) != 1:
            return {"score": 0, "detail": f"目标日期和阶段门组合应恰有一条新增决定，实际 {len(rows)} 条"}
        row = rows[0]
        expected = {
            "conversion_project_id": "CP-2025-017",
            "gate_code": "GATE_WELL_LOOP_VALIDATION",
            "decision_code": "CONDITIONAL_PROCEED_TO_WELL_AND_LOOP_VALIDATION",
            "open_condition_count": 5,
            "decision_date": "2025-08-18",
            "report_release_status": "CONTROLLED_DRAFT",
        }
        bad = {key: (row[key], value) for key, value in expected.items() if row[key] != value}
        review_status = row["technical_economic_review_status"]
        accepted_review_statuses = {
            "COMPLETE_WITH_OPEN_FIELD_CONDITIONS",
            "COMPLETED_WITH_OPEN_FIELD_CONDITIONS",
        }
        if review_status not in accepted_review_statuses:
            bad["technical_economic_review_status"] = (review_status, sorted(accepted_review_statuses))
        text = str(row["decision_text"] or "")
        if "有条件" not in text or ("不能" not in text and "不得" not in text):
            bad["decision_text_semantics"] = text
        if bad:
            return {"score": 0, "detail": f"目标决定后态不符: {bad}"}
        return {"score": 1, "detail": "新增阶段门决定的项目、阶段门、日期、决定、等价评审状态、发布状态、开放条件数及限制性文本均正确"}
    finally:
        con.close()


def check_unchanged_baseline(ws):
    root = Path(ws).parent / "system"
    checks = [
        ("enablon_conversion_gate", "conversion_projects"),
        ("enablon_conversion_gate", "screening_checks"),
        ("nrel_geophires_scenario", "model_cases"),
        ("nrel_geophires_scenario", "representative_load_bins"),
        ("nrel_geophires_scenario", "well_scenario_components"),
    ]
    for slug, table in checks:
        live = root / slug / "state.db"
        backup = root / slug / "state.db.pinned_backup"
        if not backup.exists():
            return {"score": 0, "detail": f"缺少基线快照 {backup}"}
        cols_live = _cols(live, table)
        cols_backup = _cols(backup, table)
        if cols_live != cols_backup:
            return {"score": 0, "detail": f"{slug}.{table} 结构被改动"}
        baseline = _rows(backup, table)
        live_rows = _rows(live, table)
        baseline_by_id = {row[0]: row for row in baseline}
        live_by_id = {row[0]: row for row in live_rows}
        for ident, row in baseline_by_id.items():
            if ident not in live_by_id:
                return {"score": 0, "detail": f"{slug}.{table} 删除了基线记录 {ident}"}
            if live_by_id[ident] != row:
                return {"score": 0, "detail": f"{slug}.{table} 改写了基线记录 {ident}"}
    return {"score": 1, "detail": "基线项目、筛选记录、模型案例及模型明细均未被改写或删除"}
